// Feeds come from the environment, not from the workflow, so this file stays
// generic and my own reading list stays out of the repository.
const raw = $env.RSS_FEEDS ?? '';
const urls = raw.split(',').map((s) => s.trim()).filter(Boolean);

if (!urls.length) {
  throw new Error(
    'RSS_FEEDS is empty. Set it in .env as a comma-separated list of feed URLs.'
  );
}

// One item per feed — the RSS node runs once per input item, so this fans out.
return urls.map((url) => ({ json: { url } }));

// Cheap filtering before the expensive step.
//
// The time window, deduplication and the hard cap all run on the raw feed output
// in plain JavaScript. Only what survives is sent to the model, so token cost
// scales with what is recent and distinct rather than with how much the sources
// happened to publish that day.

const WINDOW_HOURS = Number($env.DIGEST_WINDOW_HOURS ?? 24);
const MAX_ITEMS = Number($env.DIGEST_MAX_ITEMS ?? 40);

const cutoff = Date.now() - WINDOW_HOURS * 60 * 60 * 1000;
const seen = new Set();
const kept = [];
const failures = [];

for (const item of $input.all()) {
  const a = item.json;

  // The RSS node is set to continue on error, so an unreachable feed arrives
  // here as an item carrying an error instead of killing the run. Record it —
  // a digest that is quietly short is worse than one that admits a gap.
  if (a.error) {
    failures.push(String(a.error).slice(0, 200));
    continue;
  }

  const title = (a.title ?? '').trim();
  const link = (a.link ?? '').trim();
  if (!title || !link) continue;

  // Feeds disagree on which date field they populate.
  const stamp = a.isoDate ?? a.pubDate ?? a.date ?? null;
  const published = stamp ? new Date(stamp).getTime() : NaN;
  // An unparseable date is kept rather than dropped: missing a story is worse
  // than including one that may be a day old.
  if (!Number.isNaN(published) && published < cutoff) continue;

  // The same story syndicated across two feeds should appear once.
  const key = title.toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
  if (seen.has(key)) continue;
  seen.add(key);

  let source = '';
  try { source = new URL(link).hostname.replace(/^www\./, ''); } catch (e) { /* ignore */ }

  kept.push({
    title,
    url: link,
    source,
    published: stamp,
    snippet: (a.contentSnippet ?? a.content ?? '').slice(0, 600),
  });
}

// Every source failing is a different problem from a quiet news day, and should
// not be reported as one.
if (!kept.length && failures.length) {
  throw new Error(
    `All ${failures.length} feed(s) failed — check RSS_FEEDS.\n${failures.join('\n')}`
  );
}

kept.sort((x, y) => new Date(y.published ?? 0) - new Date(x.published ?? 0));
const articles = kept.slice(0, MAX_ITEMS);

// A single item carrying the whole batch — one model call instead of N.
return [{
  json: {
    count: articles.length,
    window_hours: WINDOW_HOURS,
    sources_failed: failures.length,
    articles,
  },
}];

parameters.text:
=You are building a daily reading digest. Return ONLY a valid JSON object. Do not include markdown formatting, code blocks, or conversational text.

Topics of interest:
{{ $env.DIGEST_TOPICS }}

Rules:
- Drop any article that does not clearly relate to the topics above. Being strict is correct: a short digest that is all relevant beats a long one that is padded.
- Never invent an article. Every url you return MUST appear verbatim in the input below.
- Write each summary in two sentences at most, in English, stating what happened rather than what the headline teases.

Required JSON structure:
{
  "digest": [
    {
      "title": "article title",
      "url": "article url, copied exactly from the input",
      "source": "source domain",
      "summary": "at most two sentences",
      "why_relevant": "one short clause tying it to a topic of interest"
    }
  ]
}

If nothing is relevant, return {"digest": []}.

Articles:
{{ JSON.stringify($json.articles) }}

parameters.jsCode:
// Same contract as the other two scenarios: strip the fence, then refuse to pass
// anything downstream that does not hold up.

const raw = $input.first().json.text ?? '';
const cleaned = raw.replace(/```json/gi, '').replace(/```/g, '').trim();

let parsed;
try {
  parsed = JSON.parse(cleaned);
} catch (err) {
  throw new Error(`Digest model did not return valid JSON. Raw output:\n${cleaned.slice(0, 500)}`);
}

if (!Array.isArray(parsed.digest)) {
  throw new Error(`Expected a "digest" array, got: ${JSON.stringify(parsed).slice(0, 300)}`);
}

// The check that matters most in a digest: a fabricated link looks exactly like a
// real one in an email, and the reader only finds out by clicking. So every url
// the model returns must be one that actually went in.
const sourceArticles = $('Filter recent & dedupe').first().json.articles ?? [];
const knownUrls = new Set(sourceArticles.map((a) => a.url));

const entries = [];
for (const entry of parsed.digest) {
  for (const field of ['title', 'url', 'summary']) {
    if (!entry[field]) {
      throw new Error(`Digest entry is missing "${field}": ${JSON.stringify(entry).slice(0, 200)}`);
    }
  }
  if (!knownUrls.has(entry.url)) {
    throw new Error(
      `Digest contains a url that was not in the input — the model invented it:\n${entry.url}`
    );
  }
  entries.push({
    title: entry.title,
    url: entry.url,
    source: entry.source ?? '',
    summary: entry.summary,
    why_relevant: entry.why_relevant ?? '',
  });
}

return [{
  json: {
    count: entries.length,
    reviewed: sourceArticles.length,
    window_hours: $('Filter recent & dedupe').first().json.window_hours,
    sources_failed: $('Filter recent & dedupe').first().json.sources_failed ?? 0,
    digest: entries,
  },
}];

