=<h2>Daily digest</h2>
<p style="color:#666;font-size:13px">{{ $json.count }} of {{ $json.reviewed }} articles from the last {{ $json.window_hours }} hours made the cut.{{ $json.sources_failed ? ' ' + $json.sources_failed + ' source(s) were unreachable.' : '' }}</p>
{{ $json.digest.map(a => `<div style="margin:0 0 22px"><a href="${a.url}" style="font-size:16px;font-weight:600;color:#1a1a1a;text-decoration:none">${a.title}</a><div style="color:#888;font-size:12px;margin:2px 0 6px">${a.source}</div><div style="font-size:14px;line-height:1.5">${a.summary}</div>${a.why_relevant ? `<div style="font-size:12px;color:#777;margin-top:4px">→ ${a.why_relevant}</div>` : ''}</div>`).join('') }}
